//#define SHOW_WRAP

#define WORLD_DIMENSIONS ivec2(1<<29, 1<<28)
#define HEX_TILE_DIM ivec2(512, 592)

#define IMOD(n, d) ((n) - ((n) / (d)) * (d))

#define NUM_CIRCLES 42

ivec3 hardcoded_circles[NUM_CIRCLES] = ivec3[NUM_CIRCLES](ivec3(64, 406, 64), ivec3(251, 441, 64), ivec3(299, 255, 64), ivec3(135, 145, 64), ivec3(448, 306, 64), ivec3(480, 425, 32), ivec3(417, 398, 32), ivec3(394, 222, 32), ivec3(350, 342, 32), ivec3(253, 342, 32), ivec3(230, 170, 32), ivec3(160, 499, 32), ivec3(32, 312, 32), ivec3(308, 525, 32), ivec3(32, 167, 32), ivec3(256, 573, 16), ivec3(252, 526, 16), ivec3(208, 535, 16), ivec3(157, 432, 16), ivec3(83, 324, 16), ivec3(118, 304, 16), ivec3(495, 374, 16), ivec3(439, 456, 16), ivec3(330, 410, 16), ivec3(365, 392, 16), ivec3(101, 484, 16), ivec3(493, 237, 16), ivec3(385, 93, 16), ivec3(344, 74, 16), ivec3(280, 161, 16), ivec3(224, 221, 16), ivec3(224, 295, 16), ivec3(303, 371, 16), ivec3(410, 133, 16), ivec3(172, 69, 16), ivec3(464, 176, 48), ivec3(344, 148, 48), ivec3(170, 358, 48), ivec3(166, 257, 48), ivec3(373, 469, 48), ivec3(69, 240, 48), ivec3(256, 74, 64));

uint uhash12(uvec2 src) {
    const uint M = 0x5bd1e995u;
    uint h = 1190494759u;
    src *= M; src ^= src>>24u; src *= M;
    h *= M; h ^= src.x; h *= M; h ^= src.y;
    h ^= h>>13u; h *= M; h ^= h>>15u;
    return h;
}

vec4 unpack_colour(uint colour) {
    return vec4((colour >> 24) & 0xFFu, (colour >> 16) & 0xFFu, (colour >> 8) & 0xFFu, colour & 0xFFu) / 255.0f;
}

mat2 rotate(float a) {
    float c = cos(a);
    float s = sin(a);
    return mat2(c, s, -s, c);
}

// returns the integer centre of the hexagon and a unique (enough) hash
ivec4 get_hex(ivec2 p) {

    // 886 is a magic number that comes from 512 * ((2 * 512) / 592), which approximates 512 * sqrt(3)
    // see also "Wrapping hexagon experiment": https://www.shadertoy.com/view/43KBzd

    ivec2 cell_size = ivec2(HEX_TILE_DIM.x, 886);
    ivec2 centre_offset = cell_size >> 1;

    ivec4 id = ivec4(p / cell_size, (p + centre_offset) / cell_size);
    ivec4 uv = ivec4(p - id.xy * cell_size, (p + centre_offset) - id.zw * cell_size);

    uv -= centre_offset.xyxy;

    float r = float(cell_size.y >> 1) / float(cell_size.x);
    float d1 = max(dot(abs(vec2(uv.xy) / vec2(HEX_TILE_DIM.x)), vec2(0.5, r)), abs(float(uv.x) / float(HEX_TILE_DIM.x)));
    float d2 = max(dot(abs(vec2(uv.zw) / vec2(HEX_TILE_DIM.x)), vec2(0.5, r)), abs(float(uv.z) / float(HEX_TILE_DIM.x)));

    float d = min(d1, d2);

    id *= cell_size.xyxy;
    id.xy += centre_offset;

    ivec4 h = d1 < d2 ? ivec4(uv.xy, id.xy) : ivec4(uv.zw, id.zw);

    return h;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    ivec2 xz = ivec2(fragCoord);

#ifdef SHOW_WRAP
    xz -= (ivec2(iResolution.xy) >> 1);
#endif

    if (xz.x < 0) xz.x = WORLD_DIMENSIONS.x + xz.x;
    if (xz.y < 0) xz.y = WORLD_DIMENSIONS.y + xz.y;

    ivec2 p = xz;

    ivec4 hex = get_hex(p);

    uint hash = uhash12(uvec2(hex.zw & (WORLD_DIMENSIONS - 1)));

    mat2 rot = rotate(radians(float(IMOD(hash, 6u)) * 60.));

    float t = sin(iTime) * 0.5 + 0.5;

    vec4 col = unpack_colour(hash) * t;

    ivec3 intersecting_circle = ivec3(0);
    for (int i = 0; i < NUM_CIRCLES; i++) {
        ivec3 circle = hardcoded_circles[i];
        circle.xy = ivec2(rot * vec2(circle.xy - (HEX_TILE_DIM >> 1)));
        ivec2 delta = hex.xy - circle.xy;
        if (delta.x * delta.x + delta.y * delta.y < int(float(circle.z * circle.z) * (1. - t))) {
            intersecting_circle = circle;
        }
    }

    if (intersecting_circle.z > 0) {
        col = mix(col, vec4(2.0) - t, 0.5);
    }

    fragColor = col;
}
